// Emits simulated order transactions for fault injection testing:
// Scenario 1: Transient 504 Gateway Timeout (recoverable via replay)
// Scenario 2: Permanent Schema Validation Error (fatal poison-pill payload)
return [
  {
    json: {
      transactionId: "TX-CRASH-801",
      customerEmail: "vip-client@enterprise.org",
      amount: 1450.00,
      currency: "USD",
      scenario: "transient_timeout",
      errorMessage: "ETIMEDOUT: Upstream payment gateway took longer than 30000ms",
      httpStatusCode: 504,
      payload: {
        orderId: "ORD-9901",
        items: ["Cloud Server Host", "DDoS Shield"]
      }
    }
  }
];

// Primary Execution Worker: Simulates a risky external network operation
// Configured with retry policies (exponential backoff simulation)
const item = $input.item.json;

// In a real execution this node throws an unhandled exception or receives HTTP 504.
// For automated testing, we preserve failure telemetry and handoff to the DLQ.
return {
  json: {
    status: "FAILED_AFTER_RETRIES",
    attemptsMade: 3,
    lastAttemptTimestamp: new Date().toISOString(),
    transactionId: item.transactionId,
    failedPayload: item,
    error: {
      message: item.errorMessage || "ETIMEDOUT: Connection reset by peer",
      statusCode: item.httpStatusCode || 504,
      node: "Code_ExecuteRiskyProcess"
    }
  }
};

// Global Crash Telemetry & Context Parser
// Ingests errorContext from Error_Trigger or upstream execution failure
const errorContext = $input.all()?.[0]?.json || {};
const execution = errorContext.execution || {};
const lastError = execution.error || errorContext.error || {};
const failedNode = lastError.node?.name || "Code_ExecuteRiskyProcess";
const statusCode = Number(lastError.statusCode || errorContext.httpStatusCode || 504);

// Classification rule: 502, 503, 504, 429 and ETIMEDOUT are TRANSIENT.
// 400, 401, 403, 422, SCHEMA_ERROR are PERMANENT.
const isTransient = [429, 502, 503, 504].includes(statusCode) ||
  String(lastError.message || "").toLowerCase().includes("timeout") ||
  String(lastError.message || "").toLowerCase().includes("etimedout");

const incidentId = "INC-" + Math.floor(100000 + Math.random() * 900000);

return [
  {
    json: {
      incidentId: incidentId,
      workflowId: $workflow?.id || "topic-13-recovery",
      workflowName: $workflow?.name || "Topic 13 - Error Handling & DLQ Recovery",
      failedNodeName: failedNode,
      errorMessage: lastError.message || errorContext.errorMessage || "Unhandled gateway timeout",
      httpStatusCode: statusCode,
      isTransientFault: isTransient,
      recoveryCategory: isTransient ? "AUTOMATED_REPLAY" : "MANUAL_INVESTIGATION",
      stagedPayload: errorContext.failedPayload || errorContext.payload || errorContext,
      capturedAt: new Date().toISOString()
    }
  }
];

// Stateful Dead Letter Queue (DLQ) Persistence Store
// Persists failed payloads to a durable queue with unique dlqId and replayCount
let staticData = {};
try {
  staticData = $getWorkflowStaticData('global');
} catch (e) {
  staticData = {};
}
staticData.dlqStore = staticData.dlqStore || [];

const incident = $input.item.json;
const dlqId = "DLQ-" + Date.now().toString(36).toUpperCase() + "-" + Math.floor(100 + Math.random() * 900);

const dlqEntry = {
  dlqId: dlqId,
  incidentId: incident.incidentId,
  failedNode: incident.failedNodeName,
  errorMessage: incident.errorMessage,
  statusCode: incident.httpStatusCode,
  recoveryCategory: incident.recoveryCategory,
  stagedPayload: incident.stagedPayload,
  status: "QUEUED_IN_DLQ",
  retryCount: 0,
  maxRetriesAllowed: 3,
  storedAt: new Date().toISOString()
};

staticData.dlqStore.push(dlqEntry);

return {
  json: {
    ...incident,
    dlqId: dlqId,
    dlqStored: true,
    totalItemsInDLQ: staticData.dlqStore.length
  }
};

// Self-Healing Automated Replay Scheduler (Branch 0: Transient Errors)
// Computes exponential backoff and dispatches delayed re-execution
const incident = $input.item.json;
const backoffDelaySeconds = 10; // Exponential backoff (e.g. 2^attempt * 5s)

return {
  json: {
    recoveryAction: "REPLAY_DISPATCHED",
    resolutionType: "AUTOMATED_SELF_HEALING",
    dlqId: incident.dlqId,
    incidentId: incident.incidentId,
    replayTargetEndpoint: "https://httpstat.us/200",
    scheduledDelaySeconds: backoffDelaySeconds,
    status: "REPLAY_TASK_SCHEDULED",
    originalPayload: incident.stagedPayload,
    scheduledAt: new Date().toISOString()
  }
};

// Permanent Failure Escalation (Branch 1: Non-Recoverable Poison Pills)
// Formats high-priority SRE diagnostic alert with execution link and payload
const incident = $input.item.json;

return {
  json: {
    recoveryAction: "PERMANENT_INCIDENT_ESCALATED",
    resolutionType: "MANUAL_SRE_INVESTIGATION",
    dlqId: incident.dlqId,
    incidentId: incident.incidentId,
    severity: "SEV-2_HIGH_PRIORITY",
    reason: incident.errorMessage,
    failedNode: incident.failedNodeName,
    recommendation: "Inspect payload schema; do not retry automatically",
    alertChannel: "#sre-escalations",
    escalatedAt: new Date().toISOString()
  }
};

// Master Incident Resolution Telemetry & Audit Logger
const resp = $input.item.json;

return {
  json: {
    auditStatus: "INCIDENT_INTERCEPTED_AND_QUARANTINED",
    recoveryAction: resp.recoveryAction,
    resolutionType: resp.resolutionType,
    dlqReference: resp.dlqId,
    incidentReference: resp.incidentId,
    systemState: "HEALTHY_FAILSAFE_ENGAGED",
    zeroDataLossConfirmed: true,
    completedAt: new Date().toISOString()
  }
};
